import pytest
from candidate import separate_paren_groups

class TestSeparateParenGroups:

    def test_empty_string(self):
        assert separate_paren_groups("") == []

    def test_single_open_paren(self):
        assert separate_paren_groups("(") == []

    def test_single_close_paren(self):
        assert separate_paren_groups(")") == []

    def test_balanced_group(self):
        assert separate_paren_groups("( ) (( ))") == ["()", "(())"]

    def test_nested_groups(self):
        assert separate_paren_groups("(( )) (( )( ))") == ["()", "(())", "(()())"]

    def test_unbalanced_group(self):
        assert separate_paren_groups("(( )") == ["()"]

    def test_complex_nested_groups(self):
        assert separate_paren_groups("(( ( ) ( ) ) (( ) ) ( ) (( ) ) )") == ["()", "(())", "(()())", "(( ))", "(( ))"]

    def test_mixed_content(self):
        assert separate_paren_groups("abc(( )def)ghi(jkl(mno)pqr)stu") == ["( )", "mno"]

    def test_non_balanced_input(self):
        assert separate_paren_groups("(( )")) == ["()"]

    def test_large_input(self):
        input_string = "(" * 10000 + ")" * 10000
        assert len(separate_paren_groups(input_string)) == 10000

    def test_no_parentheses(self):
        assert separate_paren_groups("abc") == []

    def test_only_open_parens(self):
        assert separate_paren_groups("(" * 10) == ["(" * 10]

    def test_only_closing_parens(self):
        assert separate_paren_groups(")" * 10) == [")" * 10]

    def test_no_matching_parentheses(self):
        assert separate_paren_groups("( ) (( )")) == ["()", "( )"]
